{
  "name": "discourse-descent",
  "version": "0.1.1",
  "description": "Consensus-based multi-agent debate as a native opencode plugin: heterogeneous debater sessions argue a question over annealed rounds; a coordinator judges convergence and synthesizes an answer; optimizer-analogy steering strategies and a transformers.js RAG memory shape the run.",
  "keywords": ["opencode", "opencode-plugin", "multi-agent", "debate", "llm", "consensus", "discourse-descent", "sdd"],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bolirev/ai-sdd.git"
  },
  "homepage": "https://github.com/bolirev/ai-sdd#readme",
  "bugs": {
    "url": "https://github.com/bolirev/ai-sdd/issues"
  },
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "discourse-descent-bench": "./dist/bench.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/plugin.d.ts",
      "import": "./dist/plugin.js"
    }
  },
  "files": ["dist", "commands", "README.md"],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "typecheck": "tsc --noEmit",
    "check": "npm run typecheck && npm test && npm run build",
    "prepublishOnly": "npm run check",
    "test": "vitest run",
    "test:watch": "vitest",
    "bench": "tsx src/bench.ts",
    "dashboard:preview": "tsx src/dashboard-preview.ts"
  },
  "dependencies": {
    "@huggingface/transformers": "^4.2.0",
    "zod": "^3.24.0",
    "zod-to-json-schema": "^3.25.2"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0",
    "@opencode-ai/sdk": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.13",
    "@opencode-ai/sdk": "^1.17.13",
    "@types/node": "^22.0.0",
    "tsup": "^8.5.1",
    "tsx": "^4.19.0",
    "typescript": "^5.6.0",
    "vitest": "^4.1.9"
  },
  "engines": {
    "node": ">=18"
  }
}

#!/usr/bin/env node
import {
  DebatePlugin,
  plugin_default
} from "./chunk-3HITHFEZ.js";
import "./chunk-XRQI6M5D.js";
export {
  DebatePlugin,
  plugin_default as default
};
//# sourceMappingURL=plugin.js.map
